Problem:
A manufacturing plant has the option to offer a shuttle bus and outsource to a taxi service. A shuttle bus costs $20 and carries 7 workers, whereas a taxi service costs $50 and carries 5 workers. The manufacturing plant has to transport at least 250 workers and at most 5 shuttle buses can be used. How many of each type of transport should be taken to minimize the total cost?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "shuttle buses",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "taxis",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "shuttle buses",
     "coef": 20.0
    },
    {
     "var": "taxis",
     "coef": 50.0
    }
   ]
  },
  "constraints": [
   {
    "name": "worker transport requirement",
    "terms": [
     {
      "var": "shuttle buses",
      "coef": 7.0
     },
     {
      "var": "taxis",
      "coef": 5.0
     }
    ],
    "sense": ">=",
    "rhs": 250.0
   },
   {
    "name": "shuttle bus limit",
    "terms": [
     {
      "var": "shuttle buses",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 5.0
   }
  ]
 },
 "facts": {
  "objective": 2250.0,
  "values": {
   "shuttle buses": 5.0,
   "taxis": 43.0
  },
  "binding": [
   "worker transport requirement",
   "shuttle bus limit"
  ],
  "slack": {
   "worker transport requirement": 0.0,
   "shuttle bus limit": 0.0
  },
  "shadow_prices": null
 }
}
